#include<bits/stdc++.h>

using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;

    int t = 0, a = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'T') ++t;
        else ++a;
    }

    if (t > a) cout << 'T' << endl;
    else if (t < a) cout << 'A' << endl;
    else cout << char('T' + 'A' - s.back()) << endl;
}

n = int(input())
s = input()

t = 0
a = 0
for i in range(0, n):
    if s[i] == 'T':
        t += 1
    else:
        a += 1

if t > a:
    print('T')
elif t < a:
    print('A')
elif s[-1] == 'A':
    print('T')
else:
    print('A')
